import "dotenv/config";
import { config } from "dotenv";
import { defineConfig } from "prisma/config";

// Carga también el archivo local del entorno (el mismo que usa la app en src/config/env.js),
// para que el CLI de Prisma (generate/migrate) vea DATABASE_URL sin exportarla a mano.
config({ path: `.env.${process.env.NODE_ENV || "development"}.local` });

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    // Fallback igual que sqlite.js, para que nunca falte la URL en local.
    url: process.env["DATABASE_URL"] || "file:./dev.db",
  },
});
